<script setup lang="ts">
import {t,locale} from '../i18n'

import { reactive, ref, watch } from 'vue'
import type { AgentInfo, Settings } from '../../shared/types'
import Icon from './Icon.vue'
import WorkBuddyModelPicker from './WorkBuddyModelPicker.vue'
import logo from '../../../assets/qwork.svg'
const props=defineProps<{settings:Settings;agents:AgentInfo[];refreshing:boolean}>()
const emit=defineEmits<{save:[settings:Settings];refresh:[];notify:[message:string]}>()
const form=reactive({...props.settings,agentModels:{...props.settings.agentModels},allowWeb:props.settings.allowWeb!==false,themePreference:props.settings.themePreference||'system',languagePreference:props.settings.languagePreference||'system',startupTimeoutSeconds:props.settings.startupTimeoutSeconds||90,idleTimeoutSeconds:props.settings.idleTimeoutSeconds||180,progressTimeoutSeconds:props.settings.progressTimeoutSeconds||300})
form.maxRounds=Math.min(8,Math.max(1,form.maxRounds))
const testing=ref(''),tab=ref('agents')
const menus=[{id:'agents',label:'本机 Agent'},{id:'execution',label:'执行与权限'},{id:'defaults',label:'系统设置'}]
const editableModel=(kind:string)=>['codex','claude','qwen'].includes(kind)
watch(()=>props.settings.locale,value=>{form.locale=value})
function changeLanguage(){emit('save',{...form,agentModels:{...form.agentModels}})}
async function diagnostics(){try{await window.qwork!.diagnostics()}catch(error:any){emit('notify',error.message)}}
async function pick(){try{const value=await window.qwork!.pickDirectory();if(value)form.defaultDirectory=value}catch(e:any){emit('notify',e.message)}}
async function test(kind:AgentInfo['kind']){testing.value=kind;try{emit('notify',await window.qwork!.testAgent(kind))}catch(e:any){emit('notify',e.message)}finally{testing.value=''}}
</script>

<template><div class="settings-page page-scroll">
<header class="page-heading"><div><h1>{{ t("让团队准备就绪。") }}</h1><p>{{ t("使用本机 Agent 的原生登录和模型配置，资料与运行记录保存在本地。") }}</p></div></header>
<nav class="settings-tabs" role="tablist" :aria-label="t('设置分类')"><button v-for="menu in menus" :key="menu.id" type="button" role="tab" :id="'settings-tab-'+menu.id" :aria-controls="'settings-panel-'+menu.id" :aria-selected="tab===menu.id" :class="{active:tab===menu.id}" @click="tab=menu.id">{{ t(menu.label) }}</button></nav>
<section v-if="tab==='agents'" id="settings-panel-agents" role="tabpanel" aria-labelledby="settings-tab-agents" class="settings-section"><div class="section-heading"><div><h2>{{ t('本机 Agent') }}</h2><p>{{ t('安装、协议兼容与模型连接是不同状态。连接测试会实际调用模型。') }}</p></div><button class="button subtle" :disabled="refreshing" @click="emit('refresh')"><Icon name="refresh" :class="{spin:refreshing}" :size="16"/>{{ refreshing?t('检测中…'):t('重新检测') }}</button></div>
<div class="agent-settings-grid"><article v-for="agent in agents" :key="agent.kind" class="agent-setting-card"><div class="label-row"><span class="avatar large" :data-agent="agent.kind">{{ agent.label.slice(0,1) }}</span><span :class="['status-chip',agent.installed&&agent.compatible?'success':'muted']">{{ !agent.installed?t('未找到 CLI'):!agent.compatible?t('协议不兼容'):t('已安装') }}</span></div><h3>{{ agent.label }}</h3><p class="agent-version">{{ agent.version||t('请在原生终端中安装并完成配置') }}</p><dl><div><dt>{{ t('模型配置') }}</dt><dd>{{ agent.credential==='ready'?t('已检测到配置'):agent.credential==='missing'?t('需要登录或配置'):t('待验证') }}</dd></div><div><dt>{{ t('资料与文件能力') }}</dt><dd>{{ t('取决于模型及本机工具') }}</dd></div></dl>
<div class="agent-model-slot"><WorkBuddyModelPicker v-if="agent.kind==='workbuddy'&&agent.installed" @notify="message=>emit('notify',message)"/><template v-else><label class="field">{{ t('执行模型') }}<input v-if="editableModel(agent.kind)" v-model="form.agentModels[agent.kind]" :aria-label="agent.label+' '+t('执行模型')" :disabled="!agent.installed||!agent.compatible" maxlength="120" :placeholder="t('留空跟随 CLI 默认模型')"><input v-else :value="t('跟随 CLI 默认模型')" disabled></label><div class="model-save-row"><small>{{ editableModel(agent.kind)?t('填写原生服务支持的模型 ID'):t('请在原生 CLI 中选择模型') }}</small><button v-if="editableModel(agent.kind)" type="button" class="button subtle" :disabled="!agent.installed||!agent.compatible" @click="changeLanguage">{{ t('保存模型') }}</button></div></template></div>
<button class="button subtle full agent-test-button" :disabled="!!testing||!agent.installed||!agent.compatible" @click="test(agent.kind)"><Icon name="link" :size="15"/>{{ testing===agent.kind?t('正在调用模型…'):t('测试连接') }}</button><p v-if="agent.error" class="error-inline" role="alert">{{ agent.error }}</p></article></div></section>
<section v-if="tab==='defaults'" id="settings-panel-defaults" role="tabpanel" aria-labelledby="settings-tab-defaults" class="settings-section"><div class="section-heading"><h2>{{ t('系统设置') }}</h2></div><form class="settings-form" @submit.prevent="changeLanguage"><div class="two-columns"><label class="field">{{ t('界面主题') }}<select data-testid="theme" v-model="form.themePreference" @change="changeLanguage"><option value="system">{{ t('跟随系统') }}</option><option value="light">{{ t('浅色 · 日间') }}</option><option value="dark">{{ t('深色 · 夜间') }}</option></select></label><label class="field">{{ t('界面语言') }}<select data-testid="language" v-model="form.languagePreference" @change="changeLanguage"><option value="system">{{ t('跟随电脑语言') }}</option><option value="zh">{{ t('中文') }}</option><option value="en">English</option></select></label></div><label class="field">{{ t('新群聊默认位置') }}<div class="input-action"><input v-model="form.defaultDirectory" required><button type="button" class="button subtle" @click="pick"><Icon name="folder" :size="16"/>{{ t('选择目录') }}</button></div></label><button class="button primary">{{ t('保存设置') }}<Icon name="check" :size="16"/></button></form></section>
<section v-if="tab==='execution'" id="settings-panel-execution" role="tabpanel" aria-labelledby="settings-tab-execution" class="settings-section"><div class="section-heading"><h2>{{ t('执行与权限') }}</h2><button type="button" class="button subtle" @click="diagnostics">{{ t('导出脱敏诊断') }}</button></div><form class="settings-form" @submit.prevent="changeLanguage"><label class="check-field"><input data-testid="allow-web" v-model="form.allowWeb" type="checkbox" @change="changeLanguage"><span>{{ t('允许 Agent 联网查资料') }}</span></label><div class="two-columns"><label class="field">{{ t('默认讨论轮数上限') }}<input v-model.number="form.maxRounds" type="number" min="1" max="8" required><small>{{ t('达到结束条件即提前结束。') }}</small></label><label class="field">{{ t('单次 Agent 调用超时（分钟）') }}<input v-model.number="form.timeoutMinutes" type="number" min="1" max="120" required></label></div><section class="resilience-settings"><h3>{{ t('Agent 异常检测') }}</h3><div class="two-columns"><label class="field">{{ t('启动后无反馈上限（秒）') }}<input v-model.number="form.startupTimeoutSeconds" type="number" min="10" max="1800" required></label><label class="field">{{ t('无活动上限（秒）') }}<input v-model.number="form.idleTimeoutSeconds" type="number" min="10" max="1800" required></label><label class="field">{{ t('无实质进展上限（秒）') }}<input v-model.number="form.progressTimeoutSeconds" type="number" min="10" max="3600" required></label></div></section><button class="button primary">{{ t('保存设置') }}<Icon name="check" :size="16"/></button></form></section>
<section class="about-card"><img :src="logo" alt="Qwork" width="42" height="42"><div><strong>Qwork <span class="optional">0.1.3</span></strong><p>{{ t('多Agent协作工作台 · 基于 Meldwork 的 CLI 兼容层重新设计。Apache-2.0，相关归属见 LICENSE / NOTICE。') }}</p></div></section>
</div></template>
<style scoped>.settings-tabs{display:flex;gap:6px;border-bottom:1px solid var(--line);margin:0 0 24px}.settings-tabs button{border:0;border-bottom:2px solid transparent;background:none;color:var(--muted);padding:14px 20px;font-weight:500}.settings-tabs button.active{color:var(--accent);border-bottom-color:var(--accent)}.agent-setting-card{display:flex;flex-direction:column;padding:22px}.agent-setting-card h3{margin-top:16px}.agent-model-slot{border-top:1px solid var(--line);padding-top:16px;margin-top:12px;min-height:158px}.agent-model-slot .field{margin:0 0 10px}.agent-model-slot input{width:100%;font-size:13px}.model-save-row{display:flex;align-items:center;justify-content:space-between;gap:8px}.model-save-row small{color:var(--muted);font-size:11px;line-height:1.6}.model-save-row .button{padding:8px 11px}.agent-test-button{margin-top:auto}.agent-model-slot :deep(.workbuddy-picker){border:0;padding:0;margin:0}.settings-tabs{overflow-x:auto}.settings-tabs button{white-space:nowrap}</style>
